files.src/Reversing.st:
PROGRAM Reversing
VAR_INPUT FwdPB AT %I0.0 : BOOL; RevPB AT %I0.1 : BOOL; StopPB AT %I0.2 : BOOL; LubeOk AT %I0.3 : BOOL; END_VAR
VAR_OUTPUT Forward AT %Q0.0 : BOOL; Reverse AT %Q0.1 : BOOL; END_VAR
Forward := (FwdPB OR Forward) AND NOT StopPB AND LubeOk AND NOT Reverse;
Reverse := (RevPB OR Reverse) AND NOT StopPB AND LubeOk AND NOT Forward;
END_PROGRAM

